<?php $pc=product_card_data($p);$discount=$pc['display_price']<(float)$pc['sale_price'];?><article class="product-card"><div class="product-media"><a href="<?=app_url('product.php?slug='.urlencode($pc['slug']))?>"><?php if($pc['primary_image']):?><img src="<?=app_url($pc['primary_image'])?>" alt="<?=h($pc['name'])?>" loading="lazy"><?php else:?><div class="product-placeholder"><span><?=h(mb_substr($pc['name'],0,1))?></span><small>TOPLUCA</small></div><?php endif;?></a><div class="badges"><?php if($discount):?><span class="badge orange">Fırsat</span><?php endif;?><?php if((int)$pc['is_new']):?><span class="badge dark">Yeni</span><?php endif;?></div><a class="heart" href="<?=app_url('favorites.php?action=toggle&product='.(int)$pc['id'])?>" aria-label="Favoriye ekle">♡</a></div><div class="product-content"><div class="product-brand"><?=h($pc['brand_name']??'')?></div><a class="product-title" href="<?=app_url('product.php?slug='.urlencode($pc['slug']))?>"><?=h($pc['name'])?></a><div class="product-meta"><span>★★★★★</span><small>Ürün Kodu: <?=h($pc['sku'])?></small></div><div class="price-area"><?php if($discount||($pc['compare_price']!==null&&(float)$pc['compare_price']>(float)$pc['display_price'])):?><del><?=money($pc['compare_price']?:$pc['sale_price'])?></del><?php endif;?><strong><?=money($pc['display_price'])?></strong><small>KDV dahil</small></div><?php if($pc['tier_hint']):?><div class="tier-hint"><b><?= (int)$pc['tier_hint']['min_qty'] ?>+ adet</b> alımda <?=money($pc['tier_hint']['unit_price'])?> / adet</div><?php endif;?><form class="card-cart" action="<?=app_url('cart.php')?>" method="post"><?=csrf_field()?><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=(int)$pc['id']?>"><div class="qty-control"><button type="button" data-qty-minus>−</button><input type="number" name="quantity" min="1" max="99" value="1"><button type="button" data-qty-plus>+</button></div><button class="cart-button" type="submit">Sepete Ekle</button></form><div class="delivery-line"><?php if($pc['shipping_policy']==='free'):?><span>✓ Ücretsiz kargo</span><?php elseif((int)$pc['same_day_delivery']):?><span>⚡ Ankara aynı gün uygun</span><?php else:?><span>🚚 Hızlı gönderim</span><?php endif;?></div></div></article>